class K{String s(boolean p,String[]l){int h=l.length,w=l[0].length(),z=p?1:999999,n=0,x[]=new int[h*w],y[]=x.clone();for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(l[i].charAt(j)<40){x[n]=i;y[n++]=j;}java.util.Arrays.sort(y,0,n);long A=0,s;for(var a:new int[][]{x,y}){s=0;int d=0,q=-1;for(int i=0;i<n;i++){if(a[i]>q){q=a[i];d++;}long v=a[i]+(long)z*(a[i]+1-d);A+=v*i-s;s+=v;}}return A+"";}}
